async def seed_database():
    async with engine.begin() as conn:
        await conn.run_sync(Base.metadata.create_all)

    async with AsyncSessionLocal() as session:
        # Clear existing challenges and reseed with job-ready curriculum
        await session.execute(delete(Challenge))
        await session.execute(delete(Achievement))

        for item in JOB_FOCUSED_CHALLENGES:
            new_ch = Challenge(
                level_number=item["level_number"],
                chapter_id=item["chapter_id"],
                chapter_title=item["chapter_title"],
                title=item["title"],
                story=item["story"],
                objective=item["objective"],
                starter_code=item["starter_code"],
                expected_output=item["expected_output"],
                hints_json=json.dumps(item["hints"]),
                test_cases_json=json.dumps(item["test_cases"]),
                explanation=item["explanation"],
                xp_reward=item["xp_reward"],
                coin_reward=item["coin_reward"],
                is_boss=item["is_boss"],
                boss_name=item.get("boss_name"),
                boss_hp=item.get("boss_hp"),
                difficulty=item["difficulty"]
            )
            session.add(new_ch)

        for ach in ACHIEVEMENTS_DATA:
            new_ach = Achievement(
                code=ach["code"],
                title=ach["title"],
                description=ach["description"],
                icon=ach["icon"],
                category=ach["category"],
                xp_bonus=ach["xp_bonus"],
                coin_bonus=ach["coin_bonus"]
            )
            session.add(new_ach)

        # Seed admin and student account
        admin_check = await session.execute(select(User).where(User.username == "admin"))
        if not admin_check.scalars().first():
            admin_user = User(
                username="admin",
                email="admin@pythonquest.io",
                hashed_password=hash_password("admin123"),
                role="admin",
                xp=5000,
                coins=1500,
                level=10,
                streak=15
            )
            session.add(admin_user)

        guest_check = await session.execute(select(User).where(User.username == "student_dev"))
        if not guest_check.scalars().first():
            guest_user = User(
                username="student_dev",
                email="student@pythonquest.io",
                hashed_password=hash_password("student123"),
                role="user",
                xp=100,
                coins=100,
                level=1,
                streak=1
            )
            session.add(guest_user)

        await session.commit()


if __name__ == "__main__":
    asyncio.run(seed_database())
    print("Seeding completed successfully with all 50 job interview challenges!")
